import{_ as a,c as t,o as s,al as i}from"./chunks/framework.DM883ANZ.js";const m=JSON.parse('{"title":"자주 묻는 질문","description":"자주 묻는 질문 — MAVLink message, enum and command reference.","frontmatter":{"head":[["meta",{"property":"og:title","content":"자주 묻는 질문"}],["meta",{"property":"og:description","content":"자주 묻는 질문 — MAVLink message, enum and command reference."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://mavlink.io/ko/about/faq.html"}],["link",{"rel":"canonical","href":"https://mavlink.io/ko/about/faq.html"}]]},"headers":[],"relativePath":"ko/about/faq.md","filePath":"ko/about/faq.md","lastUpdated":1790026695000}'),n={name:"ko/about/faq.md"};function o(r,e,h,l,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="자주-묻는-질문" tabindex="-1">자주 묻는 질문 <a class="header-anchor" href="#자주-묻는-질문" aria-label="Permalink to &quot;자주 묻는 질문&quot;">​</a></h1><h2 id="사용자" tabindex="-1">사용자 <a class="header-anchor" href="#사용자" aria-label="Permalink to &quot;사용자&quot;">​</a></h2><h3 id="how-efficient-is-mavlink" tabindex="-1">How efficient is MAVLink? <a class="header-anchor" href="#how-efficient-is-mavlink" aria-label="Permalink to &quot;How efficient is MAVLink?&quot;">​</a></h3><p>MAVLink is a very efficient protocol. MAVLink 1은 시작 부호와 패킷 손실 탐지 부분을 포함하여 패킷당 8바이트의 크기를 가집니다. MAVLink 2 has just 12 bytes of overhead (25 if signing is used), but is now a much more extensible protocol.</p><h3 id="how-many-vehicles-does-mavlink-support" tabindex="-1">How many vehicles does MAVLink support? <a class="header-anchor" href="#how-many-vehicles-does-mavlink-support" aria-label="Permalink to &quot;How many vehicles does MAVLink support?&quot;">​</a></h3><p>255 vehicles, with system IDs ranging from 1 to 255 (0 is not a valid vehicle ID).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Strictly speaking MAVLink supports 255 concurrent <em>systems</em>, and these can include a mix of vehicles, GCS, antenna trackers and other hardware.</p></div><h3 id="where-can-i-use-mavlink" tabindex="-1">Where can I use MAVLink? <a class="header-anchor" href="#where-can-i-use-mavlink" aria-label="Permalink to &quot;Where can I use MAVLink?&quot;">​</a></h3><p>MAVLink has been shown to work on multiple microcontrollers and operating systems, including ARM7, ATMega, dsPic, STM32 and Windows, Linux, MacOS, Android and iOS.</p><h3 id="how-reliable-is-mavlink" tabindex="-1">How reliable is MAVLink? <a class="header-anchor" href="#how-reliable-is-mavlink" aria-label="Permalink to &quot;How reliable is MAVLink?&quot;">​</a></h3><p>Very. MAVLink는 여건이 혹독한 다양한 통신 채널(높은 지연율/잡음) 환경에서 다양한 기체, 지상 관제국(및 타 노드)간의 통신 수행 목적으로 2009년부터 사용했습니다. It provides methods for detecting packet drops, and the well-established ITU X.25 checksum for packet corruption detection.</p><h3 id="how-secure-is-mavlink" tabindex="-1">How secure is MAVLink? <a class="header-anchor" href="#how-secure-is-mavlink" aria-label="Permalink to &quot;How secure is MAVLink?&quot;">​</a></h3><p>MAVLink provides <a href="./../guide/message_signing.html">message signing</a>, which allows systems to authenticate that messages are from a trusted source. MAVLink does not provide message encryption.</p><h3 id="what-version-of-mavlink-should-i-use" tabindex="-1">What version of MAVLink should I use? <a class="header-anchor" href="#what-version-of-mavlink-should-i-use" aria-label="Permalink to &quot;What version of MAVLink should I use?&quot;">​</a></h3><p>You should use the <a href="./../guide/mavlink_2.html">MAVLink 2</a> protocol where at all possible (it fixes a number of limitations of earlier versions). The <em>MAVLink 2</em> libraries also support <em>MAVLink 1</em>, so you can use them to communicate with legacy systems if needed.</p><h3 id="how-often-is-mavlink-updated-released" tabindex="-1">How often is MAVLink updated/released? <a class="header-anchor" href="#how-often-is-mavlink-updated-released" aria-label="Permalink to &quot;How often is MAVLink updated/released?&quot;">​</a></h3><ul><li>The underlying over-the-wire format is rarely updated (we&#39;re only up to <em>MAVLink 2</em>, which was introduced in 2017).</li><li>New <a href="./../messages/common.html">messages</a>/<a href="./../services/">microservices</a> are frequently added. This is a backwards compatible change, and users are expected to regularly update their libraries to support new messages.</li><li>Messages are rarely modified (or removed) such that they would become incompatible. If this is needed the project will update the MAVLink minor version number and notify users through the <a href="https://groups.google.com/forum/#!forum/mavlink" target="_blank" rel="noreferrer">mailing list</a> (users can also query the version in code).</li></ul><h2 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h2><h3 id="can-i-use-mavlink-in-a-closed-source-application-without-copyright-issues" tabindex="-1">Can I use MAVLink in a closed source application without copyright issues? <a class="header-anchor" href="#can-i-use-mavlink-in-a-closed-source-application-without-copyright-issues" aria-label="Permalink to &quot;Can I use MAVLink in a closed source application without copyright issues?&quot;">​</a></h3><p>Yes, without any limitations. The generated MAVLink library headers are made available under the <em>MIT license</em> (for more information see: <a href="./../#license">Introduction &gt; License</a>).</p><h3 id="how-does-mavlink-detect-and-decode-messages-in-the-byte-stream" tabindex="-1">How does MAVLink detect and decode messages in the byte stream? <a class="header-anchor" href="#how-does-mavlink-detect-and-decode-messages-in-the-byte-stream" aria-label="Permalink to &quot;How does MAVLink detect and decode messages in the byte stream?&quot;">​</a></h3><p>MAVLink waits for the packet start sign, then reads the packet length and matches the checksum after n bytes. If the checksum matches, it returns the decoded packet and waits again for the start sign. If bytes are altered or lost, it will drop the current message and continue the next try on the following message.</p><h3 id="mavlink-uses-only-one-start-sign-isn-t-this-less-safe-than-using-two-or-three-start-signs" tabindex="-1">MAVLink uses only one start sign - isn&#39;t this less safe than using two or three start signs? <a class="header-anchor" href="#mavlink-uses-only-one-start-sign-isn-t-this-less-safe-than-using-two-or-three-start-signs" aria-label="Permalink to &quot;MAVLink uses only one start sign - isn&#39;t this less safe than using two or three start signs?&quot;">​</a></h3><p>No. We use the CRC check to reliably determine whether a complete message has been received. Using additional start signs may increase likelihood of detecting the start point, but would provide no greater certainty of message validity. Since extra signs would increase bytes on the communication link, we choose not to use them.</p><h3 id="what-are-the-system-and-component-ids-for" tabindex="-1">What are the system and component IDs for? <a class="header-anchor" href="#what-are-the-system-and-component-ids-for" aria-label="Permalink to &quot;What are the system and component IDs for?&quot;">​</a></h3><p>The system ID represents the identity of a particular <em>MAVLink system</em> (vehicle, GCS, etc.). MAVLink can be used with up to 255 systems at the same time. The component ID reflects a component that is part of a larger system - for example a system might include an autopilot, companion computer and/or camera, which can be separately addressed. The component ID therefore lets MAVLink be used for both on- and off-board communication.</p><h3 id="why-is-the-sequence-number-in-the-mavlink-header-needed" tabindex="-1">Why is the sequence number in the MAVLink header needed? <a class="header-anchor" href="#why-is-the-sequence-number-in-the-mavlink-header-needed" aria-label="Permalink to &quot;Why is the sequence number in the MAVLink header needed?&quot;">​</a></h3><p>MAVLink is part of the safety critical components of an unmanned air system. A bad communication link dropping many packets can endanger the flight safety of the aircraft and has to be monitored. Having the sequence in the header allows MAVLink to continuously provide feedback about the packet drop rate and thus allows the aircraft or ground control station to take action.</p><h3 id="why-is-crc-extra-needed-in-the-packet-checksum" tabindex="-1">Why is CRC_EXTRA needed in the packet checksum? <a class="header-anchor" href="#why-is-crc-extra-needed-in-the-packet-checksum" aria-label="Permalink to &quot;Why is CRC_EXTRA needed in the packet checksum?&quot;">​</a></h3><p>The CRC_EXTRA CRC is used to verify that the sender and receiver have a shared understanding of the over-the-wire format of a particular message (required because as a lightweight protocol, the message structure isn&#39;t included in the payload).</p><p>In MAVLink 0.9 the CRC was not used (although there was a length check). There were a small number of cases where XML describing a message changed without changing the message length, leading to badly corrupted fields when messages were read.</p><h3 id="i-would-like-to-help-improve-the-decoding-encoding-routines-or-other-features-can-mavlink-be-changed" tabindex="-1">I would like to help improve the decoding/encoding routines or other features. Can MAVLink be changed? <a class="header-anchor" href="#i-would-like-to-help-improve-the-decoding-encoding-routines-or-other-features-can-mavlink-be-changed" aria-label="Permalink to &quot;I would like to help improve the decoding/encoding routines or other features. Can MAVLink be changed?&quot;">​</a></h3><p>Yes, but only very, very carefully with safety testing.</p><p>MAVLink is used as a safety-critical component in many autopilot systems and has undergone many years of testing. Please suggest new features on the MAVLink <a href="./../#support">support channels</a>.</p><h3 id="how-can-i-further-reduce-the-generated-c-library-size" tabindex="-1">How can I further reduce the generated C library size? <a class="header-anchor" href="#how-can-i-further-reduce-the-generated-c-library-size" aria-label="Permalink to &quot;How can I further reduce the generated C library size?&quot;">​</a></h3><p>On extremely resource-constrained systems you may be able to reduce the size of the generated library by setting <code>MAVLINK_COMM_NUM_BUFFERS=1</code> and <code>MAVLINK_MAX_PAYLOAD_LEN</code>=&quot;size of your largest buffer&quot; (assuming only one comm link and that your payload is less than the maximum supported by MAVLink). You should also make sure that any buffers you use to pass into MAVLink are also as small as possible (e.g. the one passed into <code>mavlink_msg_to_send_buffer()</code>).</p><p>Another alternative is to use one of the other generators. For example <a href="https://github.com/olliw42/fastmavlink" target="_blank" rel="noreferrer">fastMavlink</a> asserts that it is smaller and more efficient than the libraries generated by mavgen (this has not been validated by the MAVLink project).</p>',37)])])}const p=a(n,[["render",o]]);export{m as __pageData,p as default};
